import numpy as np
def equation(eps, T, params):
    a,b,c,d,e,f,g,k,k1,q = params[:10]
    s=np.sqrt(T)
    return (a+b*s+c*T**2)+(d+e*s+f*T**2)*eps+g*np.exp(-(k+k1*T)*eps)+q*np.log(eps)
